      "cvar_engine.cpp": "#include \"cvar_engine.h\"\n#include <cctype>\n\nnamespace cs2::engine2 {\n\nCCvarEngine::CCvarEngine() {\n    RegisterConVar(\"sv_cheats\", \"0\", FCVAR_REPLICATED | FCVAR_NOTIFY, \"Allows cheats on server.\");\n    RegisterConVar(\"sv_friction\", \"5.2\", FCVAR_REPLICATED, \"World ground friction scalar.\");\n    RegisterConVar(\"cl_interp\", \"0.015625\", FCVAR_CLIENTDLL, \"Client interpolation duration.\");\n}\n\nCCvarEngine& CCvarEngine::Get() {\n    static CCvarEngine s_Instance;\n    return s_Instance;\n}\n\nuint32_t CCvarEngine::HashConVarName(const std::string& name) noexcept {\n    // Caseless 32-bit FNV-1a hash matching engine2.dll seed 0x31415926\n    uint32_t hash = 0x31415926;\n    for (char c : name) {\n        hash ^= static_cast<uint8_t>(std::tolower(static_cast<unsigned char>(c)));\n        hash *= 0x01000193;\n    }\n    return hash;\n}\n\nvoid CCvarEngine::RegisterConVar(const std::string& name, const std::string& defaultValue, uint32_t flags, const std::string& help) {\n    m_ConVars[name] = { name, defaultValue, flags, help };\n}\n\nconst ConVarRecord* CCvarEngine::FindConVar(const std::string& name) const {\n    auto it = m_ConVars.find(name);\n    return it != m_ConVars.end() ? &it->second : nullptr;\n}\n\nbool CCvarEngine::IsCheatProtected(const std::string& name) const {\n    const auto* cvar = FindConVar(name);\n    return cvar && (cvar->flags & FCVAR_CHEAT) != 0;\n}\n\nbool CCvarEngine::IsReplicated(const std::string& name) const {\n    const auto* cvar = FindConVar(name);\n    return cvar && (cvar->flags & FCVAR_REPLICATED) != 0;\n}\n\nbool CCvarEngine::SetClientConVar(const std::string& name, const std::string& newValue, bool isServerCall) {\n    auto it = m_ConVars.find(name);\n    if (it == m_ConVars.end()) {\n        return false;\n    }\n\n    // Gatekeeper 1: FCVAR_REPLICATED (Bit 13) cannot be modified by client unless pushed by server\n    if ((it->second.flags & FCVAR_REPLICATED) && !isServerCall) {\n        return false; // Unauthorized client overwrite rejected\n    }\n\n    // Gatekeeper 2: FCVAR_CHEAT (Bit 14) requires sv_cheats == \"1\"\n    if ((it->second.flags & FCVAR_CHEAT)) {\n        const auto* svCheats = FindConVar(\"sv_cheats\");\n        if (!svCheats || svCheats->value != \"1\") {\n            return false; // Cheats are not enabled\n        }\n    }\n\n    it->second.value = newValue;\n    return true;\n}\n\n} // namespace cs2::engine2\n",
      "cvar_engine.h": "#ifndef CS2_ENGINE2_CVAR_ENGINE_H\n#define CS2_ENGINE2_CVAR_ENGINE_H\n\n#include <cstdint>\n#include <string>\n#include <unordered_map>\n\nnamespace cs2::engine2 {\n\n// ConVar Bit Flags verified from engine2.dll @ 0x1800825e0\nconstexpr uint32_t FCVAR_NONE               = 0;\nconstexpr uint32_t FCVAR_UNREGISTERED       = (1 << 0);\nconstexpr uint32_t FCVAR_DEVELOPMENTONLY    = (1 << 1);\nconstexpr uint32_t FCVAR_GAMEDLL            = (1 << 2);\nconstexpr uint32_t FCVAR_CLIENTDLL          = (1 << 3);\nconstexpr uint32_t FCVAR_HIDDEN             = (1 << 4);\nconstexpr uint32_t FCVAR_PROTECTED          = (1 << 5);\nconstexpr uint32_t FCVAR_NOTIFY             = (1 << 8);\nconstexpr uint32_t FCVAR_REPLICATED         = (1 << 13); // Bit 13 / 0x2000: Server authoritative\nconstexpr uint32_t FCVAR_CHEAT              = (1 << 14); // Bit 14 / 0x4000: Protected by sv_cheats\n\nstruct ConVarRecord {\n    std::string name;\n    std::string value;\n    uint32_t flags = 0;\n    std::string helpString;\n};\n\n/**\n * @brief Reconstructed CCvar Engine Subsystem from engine2.dll\n * Implements FCVAR security gates, caseless string hashing, and authoritative synchronization.\n */\nclass CCvarEngine {\npublic:\n    static CCvarEngine& Get();\n\n    void RegisterConVar(const std::string& name, const std::string& defaultValue, uint32_t flags, const std::string& help);\n    [[nodiscard]] const ConVarRecord* FindConVar(const std::string& name) const;\n\n    bool SetClientConVar(const std::string& name, const std::string& newValue, bool isServerCall);\n    [[nodiscard]] bool IsCheatProtected(const std::string& name) const;\n    [[nodiscard]] bool IsReplicated(const std::string& name) const;\n\n    static uint32_t HashConVarName(const std::string& name) noexcept;\n\nprivate:\n    CCvarEngine();\n    std::unordered_map<std::string, ConVarRecord> m_ConVars;\n};\n\n} // namespace cs2::engine2\n\n#endif // CS2_ENGINE2_CVAR_ENGINE_H\n",
      "game_events.cpp": "#include \"game_events.h\"\n#include <algorithm>\n\nnamespace cs2::engine2 {\n\nCGameEventDispatcher& CGameEventDispatcher::Get() {\n    static CGameEventDispatcher s_Instance;\n    return s_Instance;\n}\n\nvoid CGameEventDispatcher::RegisterEventDescriptor(uint32_t id, const std::string& name, const std::vector<EventKeyDescriptor>& keys) {\n    m_DescriptorsById[id] = { id, name, keys };\n    m_IdByName[name] = id;\n}\n\nvoid CGameEventDispatcher::AddListener(const std::string& eventName, IGameEventListener* listener) {\n    auto it = m_IdByName.find(eventName);\n    if (it != m_IdByName.end() && listener) {\n        m_Listeners[it->second].push_back(listener);\n    }\n}\n\nvoid CGameEventDispatcher::RemoveListener(IGameEventListener* listener) {\n    if (!listener) return;\n    for (auto& pair : m_Listeners) {\n        auto& vec = pair.second;\n        vec.erase(std::remove(vec.begin(), vec.end(), listener), vec.end());\n    }\n}\n\nvoid CGameEventDispatcher::DispatchEvent(const EventInstance& ev) {\n    auto it = m_Listeners.find(ev.eventId);\n    if (it != m_Listeners.end()) {\n        for (auto* listener : it->second) {\n            if (listener) {\n                listener->OnEventFired(ev);\n            }\n        }\n    }\n}\n\n} // namespace cs2::engine2\n",
      "game_events.h": "#ifndef CS2_ENGINE2_GAME_EVENTS_H\n#define CS2_ENGINE2_GAME_EVENTS_H\n\n#include <cstdint>\n#include <string>\n#include <vector>\n#include <unordered_map>\n\nnamespace cs2::engine2 {\n\nstruct EventKeyDescriptor {\n    std::string keyName;\n    int dataType; // 1: bool, 2: int32, 3: float, 4: string\n};\n\nstruct EventDescriptor {\n    uint32_t eventId;\n    std::string eventName;\n    std::vector<EventKeyDescriptor> keys;\n};\n\nstruct EventInstance {\n    uint32_t eventId;\n    std::unordered_map<std::string, std::string> values;\n};\n\nclass IGameEventListener {\npublic:\n    virtual ~IGameEventListener() = default;\n    virtual void OnEventFired(const EventInstance& ev) = 0;\n};\n\n/**\n * @brief Reconstructed 2-Phase GameEvent Dispatcher from engine2.dll\n * Phase 1: CSVCMsg_GameEventList signon dictionary synchronization\n * Phase 2: CSVCMsgList_GameEvents batched wire delivery\n */\nclass CGameEventDispatcher {\npublic:\n    static CGameEventDispatcher& Get();\n\n    void RegisterEventDescriptor(uint32_t id, const std::string& name, const std::vector<EventKeyDescriptor>& keys);\n    void AddListener(const std::string& eventName, IGameEventListener* listener);\n    void RemoveListener(IGameEventListener* listener);\n\n    void DispatchEvent(const EventInstance& ev);\n\nprivate:\n    CGameEventDispatcher() = default;\n    std::unordered_map<uint32_t, EventDescriptor> m_DescriptorsById;\n    std::unordered_map<std::string, uint32_t> m_IdByName;\n    std::unordered_map<uint32_t, std::vector<IGameEventListener*>> m_Listeners;\n};\n\n} // namespace cs2::engine2\n\n#endif // CS2_ENGINE2_GAME_EVENTS_H\n"
