      "schemasystem.cpp": "#include \"schemasystem.h\"\n\nnamespace cs2::schemasystem {\n\nCSchemaSystem& CSchemaSystem::Get() {\n    static CSchemaSystem instance;\n    return instance;\n}\n\nCSchemaSystem::CSchemaSystem() = default;\n\nvoid CSchemaSystem::RegisterClass(const std::string& moduleName, const std::string& className, int32_t classSize) {\n    SchemaClass cls;\n    cls.name = className;\n    cls.moduleName = moduleName;\n    cls.size = classSize;\n    m_Classes[className] = std::move(cls);\n}\n\nvoid CSchemaSystem::RegisterField(const std::string& className, const std::string& fieldName, const std::string& type, int32_t offset) {\n    auto it = m_Classes.find(className);\n    if (it != m_Classes.end()) {\n        it->second.fields[fieldName] = SchemaField{fieldName, type, offset};\n    }\n}\n\nconst SchemaClass* CSchemaSystem::FindDeclaredClass(const std::string& className) const {\n    auto it = m_Classes.find(className);\n    if (it != m_Classes.end()) {\n        return &it->second;\n    }\n    return nullptr;\n}\n\nint32_t CSchemaSystem::GetFieldOffset(const std::string& className, const std::string& fieldName) const {\n    const SchemaClass* cls = FindDeclaredClass(className);\n    if (!cls) return -1;\n\n    auto it = cls->fields.find(fieldName);\n    if (it != cls->fields.end()) {\n        return it->second.offset;\n    }\n    return -1;\n}\n\n} // namespace cs2::schemasystem\n",
      "schemasystem.h": "#ifndef CS2_SCHEMASYSTEM_H\n#define CS2_SCHEMASYSTEM_H\n\n#include <cstdint>\n#include <string>\n#include <string_view>\n#include <unordered_map>\n\nnamespace cs2::schemasystem {\n\nstruct SchemaField {\n    std::string name;\n    std::string type;\n    int32_t offset;\n};\n\nstruct SchemaClass {\n    std::string name;\n    std::string moduleName;\n    int32_t size;\n    std::unordered_map<std::string, SchemaField> fields;\n};\n\n/**\n * @brief Reconstructed CSchemaSystem from schemasystem.dll\n * Verified MurmurHash2 implementation matching schemasystem.dll @ 0x180010380.\n */\nclass CSchemaSystem {\npublic:\n    static CSchemaSystem& Get();\n\n    static constexpr uint32_t MurmurHash2(std::string_view str) noexcept {\n        const uint32_t len = static_cast<uint32_t>(str.length());\n        if (len == 0) return 0;\n\n        constexpr uint32_t m = 0x5bd1e995;\n        constexpr int r = 24;\n\n        uint32_t h = len ^ 0xbaadfeed;\n        const char* data = str.data();\n        uint32_t remaining = len;\n\n        while (remaining >= 4) {\n            uint32_t k = static_cast<uint8_t>(data[0]) |\n                        (static_cast<uint8_t>(data[1]) << 8) |\n                        (static_cast<uint8_t>(data[2]) << 16) |\n                        (static_cast<uint8_t>(data[3]) << 24);\n\n            k *= m;\n            k ^= k >> r;\n            k *= m;\n\n            h *= m;\n            h ^= k;\n\n            data += 4;\n            remaining -= 4;\n        }\n\n        if (remaining == 3) h ^= static_cast<uint8_t>(data[2]) << 16;\n        if (remaining >= 2) h ^= static_cast<uint8_t>(data[1]) << 8;\n        if (remaining >= 1) {\n            h ^= static_cast<uint8_t>(data[0]);\n            h *= m;\n        }\n\n        h ^= h >> 13;\n        h *= m;\n        h ^= h >> 15;\n\n        return h;\n    }\n\n    void RegisterClass(const std::string& moduleName, const std::string& className, int32_t classSize);\n    void RegisterField(const std::string& className, const std::string& fieldName, const std::string& type, int32_t offset);\n\n    [[nodiscard]] const SchemaClass* FindDeclaredClass(const std::string& className) const;\n    [[nodiscard]] int32_t GetFieldOffset(const std::string& className, const std::string& fieldName) const;\n\nprivate:\n    CSchemaSystem();\n    std::unordered_map<std::string, SchemaClass> m_Classes;\n};\n\n} // namespace cs2::schemasystem\n\n#endif // CS2_SCHEMASYSTEM_H\n"
