      "sound_ops.cpp": "#include \"sound_ops.h\"\n\nnamespace cs2::soundsystem {\n\nCSoundManager& CSoundManager::Get() {\n    static CSoundManager s_Instance;\n    return s_Instance;\n}\n\ninterfaces::StartSoundEventInfo_t CSoundManager::CreateSpatialSoundInfo(\n    const shared::Vector3D& origin,\n    float volume,\n    float pitch,\n    shared::CEntityHandle entity\n) noexcept {\n    interfaces::StartSoundEventInfo_t info{};\n    info.m_vecOrigin = origin;\n    info.m_flVolume = volume;\n    info.m_flPitch = pitch;\n    info.m_hEntity = entity;\n\n    // Set 3x4 identity orientation matrix at origin\n    info.m_matSpatial[0][0] = 1.0f;\n    info.m_matSpatial[1][1] = 1.0f;\n    info.m_matSpatial[2][2] = 1.0f;\n    info.m_matSpatial[0][3] = origin.x;\n    info.m_matSpatial[1][3] = origin.y;\n    info.m_matSpatial[2][3] = origin.z;\n\n    return info;\n}\n\n} // namespace cs2::soundsystem\n",
      "sound_ops.h": "#ifndef CS2_SOUNDSYSTEM_SOUND_OPS_H\n#define CS2_SOUNDSYSTEM_SOUND_OPS_H\n\n#include <cstdint>\n#include <string_view>\n#include \"../interfaces/sound_system.h\"\n#include \"../tier0/utl_string_token.h\"\n\nnamespace cs2::soundsystem {\n\n/**\n * @brief Sound operator helper & event dispatcher\n * Reconstructed from soundsystem.dll @ 0x1804ab140 and client.dll + 0xB4FB20\n */\nclass CSoundManager {\npublic:\n    static CSoundManager& Get();\n\n    /**\n     * @brief Computes 32-bit MurmurHash2 sound event identifier\n     */\n    static constexpr std::uint32_t HashSoundEvent(std::string_view name) noexcept {\n        return tier0::CUtlStringToken::Hash(name);\n    }\n\n    /**\n     * @brief Formats a 3D sound event parameter packet\n     */\n    static interfaces::StartSoundEventInfo_t CreateSpatialSoundInfo(\n        const shared::Vector3D& origin,\n        float volume = 1.0f,\n        float pitch = 1.0f,\n        shared::CEntityHandle entity = shared::CEntityHandle{}\n    ) noexcept;\n};\n\n} // namespace cs2::soundsystem\n\n#endif // CS2_SOUNDSYSTEM_SOUND_OPS_H\n"
